item.command:
/bin/zsh -lc 'tmpd=$(mktemp -d /tmp/qfactory-docs.XXXXXX); curl -fsSL http://localhost:3101/registry/engine.json > "$tmpd/engine.json"; node - "$tmpd/engine.json" <<'"'NODE'
const fs=require('fs'),crypto=require('crypto'),cp=require('child_process');
const e=JSON.parse(fs.readFileSync(process.argv[2]));
for(const d of e.documents){const b=cp.execFileSync('curl',['-fsSL','http://localhost:3101'+d.url]); const h=crypto.createHash('sha256').update(b).digest('hex'); console.log(d.file+'\\t'+h+'\\t'+(h===d.sha256?'OK':'MISMATCH')); if(h"'!==d.sha256) process.exitCode=2;}
NODE
printf '"'docs retained at %s\\n' \""'$tmpd"'

